172	    private Xzz58 getSaleBidAndValidate(Long saleBidId) {
173	        Xzz58 saleBid = saleBidQueryService.findById(saleBidId);
174	        if (saleBid == null) {
175	            throw new Xkt44Exception("판매 입찰을 찾을 수 없습니다(ID: " + saleBidId + ")");
176	        }
177	
178	        Xgg74 sale = saleBid.getSale();
179	        if (sale == null) {
180	            throw new Xnb95Exception("판매 입찰과 연결된 판매 정보가 없습니다.");
181	        }
182	
183	        return saleBid;
