212	    private void handleOrderBidCreationException(Exception e, String operation) {
213	        if (e instanceof Xdg64Exception) {
214	            throw (Xdg64Exception) e;
215	        }
216	        log.error("{} 중 오류 발생: {}", operation, e.getMessage(), e);
217	        throw new Xst47Exception(operation + " 중 오류가 발생했습니다: " + e.getMessage(), e);
218	    }
