237	
238	            Xms98ResponseDto address = addressQueryService.getAddress(buyer.getEmail(), addressId);
239	
240	
241	            Xdg64 order = Xdg64.builder()
242	                    .user(buyer)
243	                    .totalAmount(saleBid.getBidPrice())
244	                    .status(Xdg64Status.PENDING_PAYMENT)
245	                    .build();
246	
247	            order = orderRepository.save(order);
248	
249	
250	            paymentRequest.setOrderId(order.getId());
251	            log.debug("결제 요청 정보: {}", paymentRequest);
252	
253	
254	            try {
255	                Xhm58 orderItem = orderItemCommandService.createOrderItem(order, saleBid.getProductSize(), saleBid.getBidPrice());
256	                order.addOrderItem(orderItem);
257	            } catch (Exception e) {
258	                log.error("주문 항목 생성 중 오류 발생: {}", e.getMessage(), e);
259	                throw new Xwg86Exception("주문 항목 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
260	            }
261	
262	
263	            try {
264	                Xhx14 orderShipment = orderShipmentCommandService.createOrderShipment(
265	                        order,
266	                        address.getRecipientName(),
267	                        address.getPhoneNumber(),
268	                        address.getZipCode(),
269	                        address.getAddress()
270	                );
271	                order.assignOrderShipment(orderShipment);
272	            } catch (Exception e) {
273	                log.error("배송 정보 생성 중 오류 발생: {}", e.getMessage(), e);
274	                throw new Xmz95Exception("배송 정보 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
