 75	                    payment = createGeneralPayment(order, user, (Xjt86RequestDto) requestDto);
 76	                    break;
 77	                default:
 78	                    throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_VALIDATION_FAILED,
 79	                            "유효하지 않은 결제 유형: " + requestDto.getPaymentType());
 80	            }
 81	
 82	
 83	            notifyUsersAndUpdateSaleStatus(order, payment);
 84	
 85	            log.info("결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
 86	                    order.getId(), payment.getId(), payment.getStatus());
 87	
 88	            return payment;
 89	        } catch (Xbf54Exception e) {
 90	            log.error("결제 처리 실패: 주문ID={}, 사용자={}, 에러코드={}, 메시지={}",
 91	                    order != null ? order.getId() : "null",
 92	                    user != null ? user.getEmail() : "null",
 93	                    e.getErrorCode().getCode(), e.getMessage());
 94	            throw e;
 95	        } catch (Exception e) {
 96	            log.error("결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 사용자={}, 오류={}",
